import pandas as pd
meta=pd.read_csv('/app/dataset/sensor_metadata.csv').set_index('sensor_id')
all=[]
for p in ['sensors_01.csv','sensors_02.csv','sensors_03.csv']:
    d=pd.read_csv('/app/dataset/'+p); all.append(d)
df=pd.concat(all,ignore_index=True).join(meta,on='sensor_id')
df['logged_time']=pd.to_datetime(df.timestamp)
df['utc_time']=df.logged_time-pd.to_timedelta(df.logger_utc_offset_hours,unit='h')
df['physical_time']=df.utc_time-pd.to_timedelta(df.response_delay_minutes,unit='m')
df['out']=(df.value<df.normal_min)|(df.value>df.normal_max)
for sid,g in df.sort_values('physical_time').groupby('sensor_id'):
    g=g.sort_values('physical_time').reset_index(drop=True)
    intervals=[]; start=None; last=None; count=0
    for _,r in g.iterrows():
        if r.out:
            if start is None: start=r.physical_time; count=0
            last=r.physical_time; count+=1
        else:
            if start is not None:
                intervals.append((start,last,count)); start=None
    if start is not None: intervals.append((start,last,count))
    if intervals:
        print('\n',sid,meta.loc[sid,'subsystem'])
        for a,b,c in intervals[:5]: print(' ',a,'to',b,'count',c,'duration_min',(b-a).total_seconds()/60+meta.loc[sid,'reporting_interval_minutes'])
        if len(intervals)>5: print(' ... total intervals',len(intervals))
